    for term in ['market research','competitor','competitor products','demo','strengths','weaknesses','personalizeforce','coachforce']:
        hits=[]
        def walk(x,path=()):
            if isinstance(x,dict):
                for k,v in x.items(): walk(v,path+(str(k),))
            elif isinstance(x,list):
                for i,v in enumerate(x): walk(v,path+(f'[{i}]',))
            elif isinstance(x,str) and term.lower() in x.lower():
                hits.append((path,x.replace('\n',' ')[:500]))
