import json,re
from pathlib import Path

text = Path('/root/question.txt').read_text()
questions = {}
for line in text.splitlines():
    line = line.strip()
    if not line or line in {'{', '}'}:
        continue
    match = re.match(r'^(?:"([^"]+)"|([A-Za-z0-9_.-]+))\s*:\s*(.*?)(?:,\s*)?$', line)
    if match:
        key = match.group(1) or match.group(2)
        questions[key] = match.group(3).strip()
if not questions:
    raise ValueError('No keyed questions parsed')
answers = {
    'q1': ['eid_1e9356f5', 'eid_4350bf70', 'eid_06cddbb3', 'eid_c3f3eff2', 'eid_24dbff62'],
    'q2': ['eid_5318af37', 'eid_fce6544f', 'eid_c9c3d8d5', 'eid_d2f0f99a', 'eid_a253c65a'],
    'q3': ['https://personaai.com/demo', 'https://smartsuggest.com/demo', 'https://tailorai.com/demo'],
}
missing = set(questions) - set(answers)
if missing:
    raise KeyError(f'Missing answers: {sorted(missing)}')
result = {}
for key in questions:
    answer = answers[key]
    result[key] = {'answer': answer, 'tokens': str(len(' '.join(answer).split()))}
Path('/root/answer.json').write_text(json.dumps(result, indent=4) + '\n')
print('parsed_keys:', list(questions))
print(Path('/root/answer.json').read_text())
