print('count',len(files))
for p in files:
    rel=p.relative_to(root)
    size=p.stat().st_size
    ext=p.suffix.lower() or '<none>'
    status=''
    try:
        b=p.read_bytes()
        try:
            text=b.decode('utf-8')
            enc='utf-8'
        except UnicodeDecodeError:
            text=b.decode('utf-8','replace'); enc='utf-8-replace'
        if ext in {'.json','.jsonl'}:
            import json
            try:
                if ext=='.json': json.loads(text)
                else:
                    for i,line in enumerate(text.splitlines(),1):
                        if line.strip(): json.loads(line)
                status='parsed-json'
            except Exception as e: status='json-error:'+type(e).__name__
        else:
            status='text'
    except Exception as e:
        enc='?'; status='read-error:'+type(e).__name__
    print(f'{rel}\t{size}\t{ext}\t{enc}\t{status}')
